param(
  [Parameter(Mandatory=$true)][string]$MppDir,
  [Parameter(Mandatory=$true)][string]$OutDir
)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Drawing\nAdd-Type -AssemblyName System.Windows.Forms
New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$shotDir = Join-Path $OutDir 'Screenshots'
New-Item -ItemType Directory -Force -Path $shotDir | Out-Null
Add-Type @'
using System;
using System.Text;
using System.Runtime.InteropServices;
public static class NativeWin32 {
  public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
  [StructLayout(LayoutKind.Sequential)]
  public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr hwnd, IntPtr hDC, uint nFlags);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool BringWindowToTop(IntPtr hWnd);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr hWnd);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);
  [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);
}
'@
function Mark([string]$m){$line="$(Get-Date -Format o) $m";Write-Host $line;Add-Content -Encoding UTF8 (Join-Path $OutDir 'capture-progress.txt') $line}
function Close-Proj($app){try{if($app.Projects.Count -gt 0){$app.FileCloseEx(0)|Out-Null}}catch{}}
function Get-ProjectHwnd {
  $procs=@(Get-Process WINPROJ -ErrorAction SilentlyContinue);foreach($p in $procs){if($p.MainWindowHandle -ne 0){return [IntPtr]$p.MainWindowHandle}}
  $script:foundHwnd=$null
  [NativeWin32]::EnumWindows({param($h,$l);if(-not [NativeWin32]::IsWindowVisible($h)){return $true};[uint32]$pid=0;[void][NativeWin32]::GetWindowThreadProcessId($h,[ref]$pid);if($procs.Id -contains [int]$pid){$len=[NativeWin32]::GetWindowTextLength($h);if($len -gt 0){$sb=New-Object Text.StringBuilder ($len+1);[void][NativeWin32]::GetWindowText($h,$sb,$sb.Capacity);if($sb.ToString().Trim().Length -gt 0){$script:foundHwnd=$h;return $false}}};return $true},[IntPtr]::Zero)|Out-Null
  if($script:foundHwnd){return [IntPtr]$script:foundHwnd};return [IntPtr]::Zero
}
function Get-ImageQuality([string]$path){
  if(!(Test-Path $path)){return [pscustomobject]@{Pass=$false;Width=0;Height=0;Range=0;Std=0;Sampled=0}}
  $bmp=[Drawing.Bitmap]::FromFile($path);try{$vals=New-Object System.Collections.Generic.List[double];$sx=[math]::Max(1,[int]($bmp.Width/80));$sy=[math]::Max(1,[int]($bmp.Height/50));for($y=0;$y -lt $bmp.Height;$y+=$sy){for($x=0;$x -lt $bmp.Width;$x+=$sx){$c=$bmp.GetPixel($x,$y);$vals.Add(0.299*$c.R+0.587*$c.G+0.114*$c.B)}};$arr=$vals.ToArray();$min=($arr|Measure-Object -Minimum).Minimum;$max=($arr|Measure-Object -Maximum).Maximum;$avg=($arr|Measure-Object -Average).Average;$sum=0.0;foreach($v in $arr){$sum+=[math]::Pow($v-$avg,2)};$std=[math]::Sqrt($sum/[math]::Max(1,$arr.Length));$range=$max-$min;$pass=($bmp.Width -ge 500 -and $bmp.Height -ge 300 -and $range -gt 25 -and $std -gt 8);return [pscustomobject]@{Pass=$pass;Width=$bmp.Width;Height=$bmp.Height;Range=[math]::Round($range,2);Std=[math]::Round($std,2);Sampled=$arr.Length}}finally{$bmp.Dispose()}
}
function Print-Window([IntPtr]$hwnd,[string]$path,[uint32]$flags){$r=New-Object NativeWin32+RECT;if(-not [NativeWin32]::GetWindowRect($hwnd,[ref]$r)){return $false};$w=$r.Right-$r.Left;$h=$r.Bottom-$r.Top;if($w -lt 100 -or $h -lt 100){return $false};$bmp=[Drawing.Bitmap]::new($w,$h,[Drawing.Imaging.PixelFormat]::Format32bppArgb);$g=[Drawing.Graphics]::FromImage($bmp);try{$hdc=$g.GetHdc();try{$ok=[NativeWin32]::PrintWindow($hwnd,$hdc,$flags)}finally{$g.ReleaseHdc($hdc)};$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);return $ok}finally{$g.Dispose();$bmp.Dispose()}}
function Copy-Screen([IntPtr]$hwnd,[string]$path){$r=New-Object NativeWin32+RECT;if(-not [NativeWin32]::GetWindowRect($hwnd,[ref]$r)){return $false};$w=$r.Right-$r.Left;$h=$r.Bottom-$r.Top;if($w -lt 100 -or $h -lt 100){return $false};$bmp=[Drawing.Bitmap]::new($w,$h);$g=[Drawing.Graphics]::FromImage($bmp);try{$g.CopyFromScreen($r.Left,$r.Top,0,0,([Drawing.Size]::new($w,$h)));$bmp.Save($path,[Drawing.Imaging.ImageFormat]::Png);return $true}catch{return $false}finally{$g.Dispose();$bmp.Dispose()}}
function Capture-ProjectWindow([string]$canonical,[string]$label){Start-Sleep -Seconds 2;$hwnd=Get-ProjectHwnd;if($hwnd -eq [IntPtr]::Zero){return [pscustomobject]@{Name=$canonical;Label=$label;Pass=$false;Method='NoWindow';Quality=$null}};[void][NativeWin32]::ShowWindow($hwnd,3);[void][NativeWin32]::BringWindowToTop($hwnd);[void][NativeWin32]::SetForegroundWindow($hwnd);Start-Sleep -Milliseconds 500;try{[System.Windows.Forms.SendKeys]::SendWait('{ESC}');Start-Sleep -Milliseconds 400;[System.Windows.Forms.SendKeys]::SendWait('{ESC}');Start-Sleep -Milliseconds 700}catch{};foreach($m in @(@{Name='PrintWindowFull';Flags=[uint32]2},@{Name='PrintWindowNormal';Flags=[uint32]0},@{Name='PrintWindowClient';Flags=[uint32]1})){$tmp=Join-Path $shotDir ($canonical.Replace('.png',"_$($m.Name).png"));$ok=Print-Window $hwnd $tmp $m.Flags;$q=Get-ImageQuality $tmp;if($ok -and $q.Pass){Copy-Item -Force $tmp (Join-Path $shotDir $canonical);return [pscustomobject]@{Name=$canonical;Label=$label;Pass=$true;Method=$m.Name;Quality=$q}}};$tmp=Join-Path $shotDir ($canonical.Replace('.png','_CopyFromScreen.png'));$ok=Copy-Screen $hwnd $tmp;$q=Get-ImageQuality $tmp;if($ok -and $q.Pass){Copy-Item -Force $tmp (Join-Path $shotDir $canonical);return [pscustomobject]@{Name=$canonical;Label=$label;Pass=$true;Method='CopyFromScreen';Quality=$q}};return [pscustomobject]@{Name=$canonical;Label=$label;Pass=$false;Method='AllFailed';Quality=$q}}
function Try-View($app,[string[]]$names){foreach($n in $names){try{$app.ViewApply($n)|Out-Null;Mark "VIEW $n";return $n}catch{}};return ''}
function Try-Table($app,[string[]]$names){foreach($n in $names){try{$app.TableApply($n)|Out-Null;Mark "TABLE $n";return $n}catch{}};return ''}
function Num($x){if($null -eq $x -or $x -eq ''){return 0.0};return [double]$x}
$expected=@('LR3_01_Baseline_V31.mpp','LR3_02_Tracking_V31.mpp','LR3_03_Risk_V31.mpp','LR4_01_Status_P1_V31.mpp','LR4_02_Status_P2_V31.mpp','LR4_03_Status_P3_V31.mpp');foreach($n in $expected){if(!(Test-Path (Join-Path $MppDir $n))){throw "Missing MPP $n"}}
$app=New-Object -ComObject MSProject.Application;$app.Visible=$true;$app.DisplayAlerts=$false;$captures=@();$accept=@();$metrics=[ordered]@{}
try{
foreach($name in $expected){$path=Join-Path $MppDir $name;Mark "OPEN $name";$app.FileOpenEx($path)|Out-Null;Start-Sleep -Seconds 1;$p=$app.ActiveProject;$all=@($p.Tasks|Where-Object{$_ -ne $null});$leaf=@($all|Where-Object{-not $_.Summary -and -not $_.Milestone});$mile=@($all|Where-Object{$_.Milestone});$res=@($p.Resources|Where-Object{$_ -ne $null -and $_.Name});$assign=0;foreach($t in $leaf){$assign+=@($t.Assignments|Where-Object{$_ -ne $null}).Count};$s=$p.ProjectSummaryTask;$m=[ordered]@{StatusDate=[string]$p.StatusDate;Cost=Num $s.Cost;BaselineCost=Num $s.BaselineCost;Work=Num $s.Work;BaselineWork=Num $s.BaselineWork;Duration=Num $s.Duration;PercentComplete=Num $s.PercentComplete;BCWS=Num $s.BCWS;BCWP=Num $s.BCWP;ACWP=Num $s.ACWP;CV=Num $s.CV;SV=Num $s.SV;CPI=Num $s.CPI;SPI=Num $s.SPI;EAC=Num $s.EAC;VAC=Num $s.VAC;Finish=[string]$s.Finish};$metrics[$name]=$m;$accept+=[pscustomobject]@{File=$name;Tasks=$all.Count;LeafTasks=$leaf.Count;Milestones=$mile.Count;Resources=$res.Count;Assignments=$assign;BaselineCost=$m.BaselineCost;StatusDate=$m.StatusDate;Pass=($leaf.Count -eq 40 -and $mile.Count -eq 8 -and $res.Count -ge 12 -and $assign -ge 40 -and $m.BaselineCost -gt 0)}
if($name -eq 'LR3_01_Baseline_V31.mpp'){[void](Try-View $app @('Диаграмма Ганта','Gantt Chart'));$captures+=Capture-ProjectWindow 'LR3_01_Gantt.png' 'Baseline Gantt';[void](Try-View $app @('Лист ресурсов','Resource Sheet'));$captures+=Capture-ProjectWindow 'LR3_02_Resources.png' 'Resource Sheet';[void](Try-View $app @('Диаграмма Ганта с отслеживанием','Tracking Gantt','Диаграмма Ганта'));[void](Try-Table $app @('Отклонения','Variance','Затраты','Cost'));$captures+=Capture-ProjectWindow 'LR3_03_Baseline.png' 'Baseline / variance'}elseif($name -eq 'LR3_02_Tracking_V31.mpp'){[void](Try-View $app @('Диаграмма Ганта с отслеживанием','Tracking Gantt','Диаграмма Ганта'));[void](Try-Table $app @('Отслеживание','Tracking','Ввод','Entry'));$captures+=Capture-ProjectWindow 'LR3_04_Tracking.png' 'Tracking model'}elseif($name -eq 'LR3_03_Risk_V31.mpp'){[void](Try-View $app @('Диаграмма Ганта','Gantt Chart'));[void](Try-Table $app @('Затраты','Cost','Ввод','Entry'));$captures+=Capture-ProjectWindow 'LR3_05_Risk.png' 'Risk model'}else{[void](Try-View $app @('Лист задач','Task Sheet','Диаграмма Ганта','Gantt Chart'));[void](Try-Table $app @('Освоенный объем','Earned Value','Затраты','Cost'));$canon=if($name -match 'P1'){'LR4_P1_EVM.png'}elseif($name -match 'P2'){'LR4_P2_EVM.png'}else{'LR4_P3_EVM.png'};$captures+=Capture-ProjectWindow $canon "EVM $name"};Close-Proj $app
}}finally{Close-Proj $app;try{$app.Quit()|Out-Null}catch{};try{[void][Runtime.InteropServices.Marshal]::ReleaseComObject($app)}catch{}}
foreach($r in $accept){$path=Join-Path $MppDir $r.File;Add-Member -InputObject $r -NotePropertyName Bytes -NotePropertyValue (Get-Item $path).Length;Add-Member -InputObject $r -NotePropertyName SHA256 -NotePropertyValue ((Get-FileHash $path -Algorithm SHA256).Hash)}
$accept|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 (Join-Path $OutDir 'Acceptance_Report_FINAL.json');$metrics|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 (Join-Path $OutDir 'project_metrics_final.json');$captures|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 (Join-Path $OutDir 'Screenshot_Capture_Report.json')
$diff=[ordered]@{BaselineVsTracking=[ordered]@{DifferentSHA=($accept[0].SHA256 -ne $accept[1].SHA256);CostDelta=($metrics['LR3_02_Tracking_V31.mpp'].Cost-$metrics['LR3_01_Baseline_V31.mpp'].Cost);WorkDelta=($metrics['LR3_02_Tracking_V31.mpp'].Work-$metrics['LR3_01_Baseline_V31.mpp'].Work);StatusDateTracking=$metrics['LR3_02_Tracking_V31.mpp'].StatusDate};BaselineVsRisk=[ordered]@{DifferentSHA=($accept[0].SHA256 -ne $accept[2].SHA256);CostDelta=($metrics['LR3_03_Risk_V31.mpp'].Cost-$metrics['LR3_01_Baseline_V31.mpp'].Cost);WorkDelta=($metrics['LR3_03_Risk_V31.mpp'].Work-$metrics['LR3_01_Baseline_V31.mpp'].Work);FinishRisk=$metrics['LR3_03_Risk_V31.mpp'].Finish};LR4=[ordered]@{P1Status=$metrics['LR4_01_Status_P1_V31.mpp'].StatusDate;P2Status=$metrics['LR4_02_Status_P2_V31.mpp'].StatusDate;P3Status=$metrics['LR4_03_Status_P3_V31.mpp'].StatusDate;P1BCWS=$metrics['LR4_01_Status_P1_V31.mpp'].BCWS;P2BCWS=$metrics['LR4_02_Status_P2_V31.mpp'].BCWS;P3BCWS=$metrics['LR4_03_Status_P3_V31.mpp'].BCWS;P1BCWP=$metrics['LR4_01_Status_P1_V31.mpp'].BCWP;P2BCWP=$metrics['LR4_02_Status_P2_V31.mpp'].BCWP;P3BCWP=$metrics['LR4_03_Status_P3_V31.mpp'].BCWP;P1ACWP=$metrics['LR4_01_Status_P1_V31.mpp'].ACWP;P2ACWP=$metrics['LR4_02_Status_P2_V31.mpp'].ACWP;P3ACWP=$metrics['LR4_03_Status_P3_V31.mpp'].ACWP}}
$diff|ConvertTo-Json -Depth 8|Set-Content -Encoding UTF8 (Join-Path $OutDir 'MPP_Difference_Check.json');Mark "CAPTURE_PASS=$(@($captures|Where-Object{$_.Pass}).Count)/$($captures.Count)"
